-- Milestone 4, step 7: the draft Clearway Map (D2-15) and the Wayfinding templates (SET-08).
-- Live only after merge and Chris's approval; the coordinator applies it. Nothing is started or
-- seeded in an engagement here: the two templates are shipped rows in private.templates.
--
-- The draft Map
--   private.map_assemble(engagement)   builds the two pages from the engagement's records
--   private.map_draft_read(engagement) facilitators and admins only; assembles, stores the pages in
--                                      private.map_drafts (a new version only when they changed)
--                                      and returns them. It is rebuilt every time the Map is opened and
--                                      never inside a phone's path, so nothing it does can slow the TV.
--   public.map_draft_read(engagement)  the invoker wrapper the app calls
-- The Map reaches no TV, no phone and no room broadcast. Participants, the TV, other engagements'
-- facilitators and strangers are denied, and private.map_drafts keeps its facilitator-only policy.
--
-- Shared objects touched (each a superset of the version before it):
--   private.template_write   adds team_led, "seeded from" (by place, never an id), a day and clock
--                            for a part's first session, lens names in titles and prompts, and
--                            a self-paced close by day and clock. Every earlier action, check and
--                            result is unchanged.
--   private.template_public  shows a lens title with its default lens name in the library.
--   New helpers: private.template_text, private.template_moment.
-- reset_practice_room, the ai_* functions and every check-constraint list are not touched.
begin;

-- ---------- Template helpers ----------
-- {lens name} in a title or prompt becomes the engagement's name for that lens (Customer replaces
-- Congregation for an organization that is not a church). Without names, the defaults.
create function private.template_text(p_text text,p_names text[],p_lens integer) returns text
language sql immutable security invoker set search_path='' as $$
 select case when p_lens between 1 and 5 then replace(coalesce(p_text,''),'{lens name}',
   coalesce(nullif(btrim(p_names[p_lens]),''),(array['Congregation','Community','Leadership','Operations','Learning'])[p_lens]))
  else coalesce(p_text,'') end
$$;
-- A day after the template's start (counted in the church's time zone) at a clock time there.
create function private.template_moment(p_zone text,p_from timestamptz,p_day integer,p_clock text) returns timestamptz
language sql immutable security invoker set search_path='' as $$
 select (((p_from at time zone p_zone)::date+p_day)::timestamp+p_clock::time) at time zone p_zone
$$;
revoke all on function private.template_text(text,text[],integer),private.template_moment(text,timestamptz,integer,text) from public,anon,authenticated;

create or replace function private.template_public(p_template private.templates) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',p_template.id,'name',p_template.name,'description',p_template.description,'kind',p_template.kind,'shared',p_template.shared,
  'mine',p_template.created_by is not null and p_template.created_by=(select private.clearway_user_id()),
  'can_remove',p_template.kind='saved' and (p_template.created_by=(select private.clearway_user_id()) or (select private.is_admin())),
  'by',(select u.name from public.clearway_users u where u.id=p_template.created_by),'created_at',p_template.created_at,
  'count',jsonb_array_length(p_template.sessions),
  'minutes',(select coalesce(sum((e->>'planned_minutes')::integer),0) from jsonb_array_elements(p_template.sessions) e where e->>'mode'='live'),
  'sessions',(select coalesce(jsonb_agg(jsonb_build_object('title',private.template_text(e->>'title',null,case when e->'options'->>'lens' ~ '^[1-5]$' then (e->'options'->>'lens')::integer end),'part',e->>'part','interaction',e->>'interaction','screen',e->'options'->>'screen',
     'planned_minutes',(e->>'planned_minutes')::integer,'mode',e->>'mode','state',e->>'state') order by private.part_order(e->>'part'),(e->>'position')::integer,n),'[]'::jsonb)
    from jsonb_array_elements(p_template.sessions) with ordinality t(e,n)))
$$;


create or replace function private.template_write(p_action text,p_input jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare me uuid:=private.clearway_user_id(); eng uuid; t private.templates; tid uuid; v_name text; v_list jsonb; anchor timestamptz;
 e jsonb; k private.interaction_kinds; opts jsonb; anon boolean; sid uuid; mid uuid; v_mode text; v_start timestamptz; base timestamptz; v_count integer:=0; anchors jsonb; p text; v_state text;
 tz text; names text[]; idmap jsonb:='{}'::jsonb; v_lens integer; v_title text; v_prompt text; v_at timestamptz; v_opens timestamptz; v_closes timestamptz;
begin
 if me is null then return jsonb_build_object('status','denied'); end if;
 if jsonb_typeof(p_input) is distinct from 'object' then return jsonb_build_object('status','invalid_request'); end if;
 if p_action='save' then
  eng:=(p_input->>'engagement')::uuid; v_name:=btrim(regexp_replace(coalesce(p_input->>'name',''),'\s+',' ','g'));
  if eng is null or not coalesce(private.show_allowed(eng),false) then return jsonb_build_object('status','denied'); end if;
  if length(v_name) not between 1 and 120 or length(coalesce(p_input->>'description',''))>500 or jsonb_typeof(coalesce(p_input->'shared','true'::jsonb)) is distinct from 'boolean' then return jsonb_build_object('status','invalid_request'); end if;
  -- The template's start is its first live session (the time Start an engagement asks for);
  -- self-paced windows keep their place around it, before or after. Without live times,
  -- the first self-paced opening.
  select coalesce((select min(planned_start) from public.sessions where engagement_id=eng and not deleted and mode='live'),
   (select min(opens_at) from public.sessions where engagement_id=eng and not deleted and mode='self_paced')) into anchor;
  select jsonb_agg(jsonb_build_object('title',s.title,'part',s.part,'position',s.position,'segment',s.segment,'mode',s.mode,'interaction',s.interaction,
    'prompt',s.prompt,'phone_depth',s.phone_depth,'lands_in',s.lands_in,'notes',coalesce(n.notes,''),'planned_minutes',s.planned_minutes,
    'offset',case when s.planned_start is not null and anchor is not null then round(extract(epoch from s.planned_start-anchor)/60)::integer end,
    'opens',case when s.mode='self_paced' then round(extract(epoch from s.opens_at-anchor)/60)::integer end,
    'closes',case when s.mode='self_paced' then round(extract(epoch from s.closes_at-anchor)/60)::integer end,
    'settings',s.settings,'options',s.options-'media','media',s.options->'media','max_sends',s.max_sends,'max_characters',s.max_characters,'max_words',s.max_words,
    'team_led',s.team_led,'key',s.part||':'||s.position,
    'seeded_from',(select x.part||':'||x.position from public.sessions x where x.id=s.seeded_from and x.engagement_id=s.engagement_id and not x.deleted),
    'state',case when s.state='draft' then 'draft' else 'ready' end) order by private.part_order(s.part),s.position,s.id) into v_list
  from (select * from public.sessions where engagement_id=eng and not deleted order by private.part_order(part),position,id limit 501) s
  left join private.session_notes n on n.session_id=s.id and not n.deleted;
  if v_list is null then return jsonb_build_object('status','empty'); end if;
  if jsonb_array_length(v_list)>500 then return jsonb_build_object('status','too_large'); end if;
  insert into private.templates(name,description,kind,shared,created_by,source_engagement_id,sessions)
   values(v_name,btrim(coalesce(p_input->>'description','')),'saved',coalesce((p_input->>'shared')::boolean,true),me,eng,v_list) returning id into tid;
  return jsonb_build_object('status','ok','id',tid,'count',jsonb_array_length(v_list));
 elsif p_action='remove' then
  select * into t from private.templates where id=(p_input->>'template')::uuid for update;
  if not found or not private.template_visible(t) then return jsonb_build_object('status','missing'); end if;
  if t.kind<>'saved' or not (t.created_by=me or coalesce(private.is_admin(),false)) then return jsonb_build_object('status','denied'); end if;
  update private.templates set deleted=true where id=t.id;
  return jsonb_build_object('status','ok','id',t.id);
 elsif p_action='apply' then
  eng:=(p_input->>'engagement')::uuid;
  if eng is null then return jsonb_build_object('status','invalid_request'); end if;
  if eng='90000000-0000-4000-8000-000000000010'::uuid then perform pg_advisory_xact_lock(hashtextextended(eng::text,7)); end if;
  perform 1 from public.room_states where engagement_id=eng and not deleted for update;
  if not found or not coalesce(private.show_allowed(eng),false) then return jsonb_build_object('status','denied'); end if;
  if exists(select 1 from public.engagements where id=eng and status='closed') then return jsonb_build_object('status','closed'); end if;
  select * into t from private.templates where id=(p_input->>'template')::uuid;
  if not found or not private.template_visible(t) then return jsonb_build_object('status','missing'); end if;
  select c.timezone,e0.lens_names into tz,names from public.engagements e0 join public.churches c on c.id=e0.church_id where e0.id=eng;
  if p_input->>'start' is not null then v_start:=(p_input->>'start')::timestamptz; if not isfinite(v_start) then return jsonb_build_object('status','invalid_request'); end if; end if;
  select jsonb_object_agg(x,private.show_anchor(eng,x)) into anchors from unnest(array['Pre-call','Day 1','Day 2','Follow-up']) x;
  base:=coalesce(v_start,date_trunc('minute',now()));
  for e in select v from jsonb_array_elements(t.sessions) with ordinality x(v,n) order by private.part_order(v->>'part'),(v->>'position')::integer,n loop
   k:=private.kind(e->>'interaction'); v_mode:=coalesce(e->>'mode','live');
   if k.kind is null or e->>'part' not in ('Pre-call','Day 1','Day 2','Follow-up') or v_mode not in ('live','self_paced') then return jsonb_build_object('status','invalid_request'); end if;
   -- A day and a clock (church time) place a part's first session after the template's start; DST-safe.
   if (e->>'day' is not null and (e->>'day' !~ '^-?[0-9]{1,3}$' or coalesce(e->>'clock','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'))
    or (e->>'closes_day' is not null and (e->>'closes_day' !~ '^-?[0-9]{1,3}$' or coalesce(e->>'closes_clock','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')) then return jsonb_build_object('status','invalid_request'); end if;
   opts:=private.session_options(k.kind,coalesce(e->'options','{}'::jsonb)-'media',eng);
   v_lens:=case when e->'options'->>'lens' ~ '^[1-5]$' then (e->'options'->>'lens')::integer end;
   v_title:=btrim(private.template_text(e->>'title',names,v_lens)); v_prompt:=private.template_text(coalesce(e->>'prompt',''),names,v_lens);
   v_at:=case when v_mode='live' and v_start is not null then case when e->>'day' is not null then private.template_moment(tz,v_start,(e->>'day')::integer,e->>'clock')
     when e->>'offset' is not null then v_start+make_interval(mins=>(e->>'offset')::integer) end end;
   v_opens:=case when v_mode='self_paced' then case when e->>'opens_day' is not null then private.template_moment(tz,coalesce(v_start,base),(e->>'opens_day')::integer,e->>'opens_clock') else base+make_interval(mins=>coalesce((e->>'opens')::integer,0)) end end;
   v_closes:=case when v_mode='self_paced' then case when e->>'closes_day' is not null then private.template_moment(tz,coalesce(v_start,base),(e->>'closes_day')::integer,e->>'closes_clock') else base+make_interval(mins=>coalesce((e->>'closes')::integer,60)) end end;
   anon:=case when jsonb_typeof(e->'settings'->'anonymous')='boolean' then (e->'settings'->>'anonymous')::boolean end;
   if opts is null or anon is null or (k.named='never' and not anon) or (k.named='always' and anon) or length(coalesce(e->>'notes',''))>30000 then return jsonb_build_object('status','invalid_request'); end if;
   v_state:=case when e->>'state'='ready' then 'ready' else 'draft' end;
   sid:=gen_random_uuid();
   insert into public.sessions(id,engagement_id,segment,title,part,position,planned_start,planned_minutes,mode,opens_at,closes_at,interaction,prompt,phone_depth,state,max_sends,max_characters,max_words,settings,options,lands_in,team_led)
   values(sid,eng,btrim(coalesce(e->>'segment','')),v_title,e->>'part',
    coalesce((select max(position)+1 from public.sessions where engagement_id=eng and part=e->>'part' and not deleted),0),
    v_at,
    (e->>'planned_minutes')::integer,v_mode,
    v_opens,
    v_closes,
    k.kind,v_prompt,coalesce(e->>'phone_depth',''),v_state,(e->>'max_sends')::integer,(e->>'max_characters')::integer,(e->>'max_words')::integer,
    jsonb_build_object('anonymous',anon,'burst_minutes',e->'settings'->'burst_minutes','join_strip',coalesce(e->'settings'->'join_strip','false'::jsonb)),opts,coalesce(e->>'lands_in',''),coalesce((e->>'team_led')::boolean,false));
   if e->>'key' is not null then idmap:=idmap||jsonb_build_object(e->>'key',sid::text); end if;
   if e->>'seeded_from' is not null then idmap:=idmap||jsonb_build_object('seed:'||sid::text,e->>'seeded_from'); end if;
   insert into private.session_notes(session_id,engagement_id,notes) values(sid,eng,coalesce(e->>'notes',''));
   -- An image or document page brings its image along as the new session's own copy.
   if k.kind='content' and e->>'media' is not null then
    mid:=null;
    insert into private.session_media(engagement_id,session_id,mime,width,height,data)
     select eng,sid,m.mime,m.width,m.height,m.data from private.session_media m where m.id=(e->>'media')::uuid returning id into mid;
    if mid is not null then update public.sessions set options=opts||jsonb_build_object('media',mid) where id=sid; end if;
   end if;
   v_count:=v_count+1;
  end loop;
  -- Seeded from: a session starts from the earlier session of the same kind that the template names.
  for e in select jsonb_build_object('sid',substr(kv.key,6),'from',kv.value) from jsonb_each_text(idmap) kv where kv.key like 'seed:%' loop
   update public.sessions s set seeded_from=(idmap->>(e->>'from'))::uuid
    where idmap ? (e->>'from') and s.id=(e->>'sid')::uuid and s.id<>(idmap->>(e->>'from'))::uuid
     and exists(select 1 from public.sessions x where x.id=(idmap->>(e->>'from'))::uuid and x.engagement_id=eng and x.interaction=s.interaction);
  end loop;
  -- A part that already had sessions keeps its start; a new one starts at the template's time.
  foreach p in array array['Pre-call','Day 1','Day 2','Follow-up'] loop
   perform private.show_retime(eng,p,coalesce((anchors->>p)::timestamptz,private.show_anchor(eng,p),case when v_start is not null and exists(select 1 from public.sessions where engagement_id=eng and part=p and not deleted and mode='live') then v_start end));
  end loop;
  update public.room_states set results=private.live_results(eng) where engagement_id=eng;
  return jsonb_build_object('status','ok','engagement',eng,'count',v_count);
 end if;
 return jsonb_build_object('status','invalid_request');
exception when invalid_text_representation or numeric_value_out_of_range or invalid_datetime_format or datetime_field_overflow or check_violation or not_null_violation or foreign_key_violation then
 return jsonb_build_object('status','invalid_request');
end $$;


-- ---------- The draft Clearway Map ----------
-- Page 1, Identity and Direction: Mission, Purpose, Values and Strategy from the church record, the
-- 10-year Future (each lens from its signed-off summary, or "Not signed off yet"), the 3-year Vision
-- (the Vision Outcomes and their indicators). Page 2, Action: This Year's Priorities (always empty,
-- left for the church's Annual Planning), the 1-year Outlook (goals that meet CORE, then the ranked
-- key metrics and the celebrations), This Season's Goals, Leadership Rhythms and Key Issues. Empty
-- fields say they are empty and why. Nothing is invented.
create function private.map_assemble(p_engagement uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare e public.engagements; c public.churches; defaults text[]:=array['Congregation','Community','Leadership','Operations','Learning'];
 lenses jsonb; outcomes jsonb; vals jsonb; rhythms jsonb; goals_met jsonb; season_goals jsonb; metrics jsonb; celebs jsonb; issues jsonb;
 first_end date; this_end date; unmet integer; season_label text;
begin
 select * into e from public.engagements where id=p_engagement and not deleted;
 if not found then return null; end if;
 select * into c from public.churches where id=e.church_id;

 select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('lens',g.n,'name',coalesce(nullif(btrim(e.lens_names[g.n]),''),defaults[g.n]),
   'state',case when ls.signed_off_version_id is not null then 'signed_off' else 'not_signed_off' end,
   'version',v.version,
   'lines',case when ls.signed_off_version_id is not null then coalesce((select jsonb_agg(s.text order by s.position) from private.lens_summary_sentences s
      where s.version_id=ls.signed_off_version_id and s.engagement_id=p_engagement and not s.deleted),'[]'::jsonb) else '[]'::jsonb end,
   'why',case when ls.signed_off_version_id is null then 'Not signed off yet' end)) order by g.n) into lenses
 from generate_series(1,5) g(n)
  left join private.lens_summaries ls on ls.engagement_id=p_engagement and ls.lens=g.n and not ls.deleted
  left join private.lens_summary_versions v on v.id=ls.signed_off_version_id and v.engagement_id=ls.engagement_id and not v.deleted;

 select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',o.id,'n',o.rn,'title',o.title,'description',nullif(o.description,''),'status',o.status,'stop',nullif(o.what_we_stop,''),
   'indicators',coalesce((select jsonb_agg(i.text order by i.position,i.created_at,i.id) from private.outcome_indicators i
      where i.outcome_id=o.id and i.engagement_id=o.engagement_id and not i.deleted and length(btrim(i.text))>0),'[]'::jsonb))) order by o.rn),'[]'::jsonb) into outcomes
 from (select x.*,row_number() over(order by x.position,x.id) as rn from private.vision_outcomes x where x.engagement_id=p_engagement and not x.deleted) o;

 select coalesce(jsonb_agg(btrim(x.v #>> '{}')),'[]'::jsonb) into vals from jsonb_array_elements(c."values") x(v) where jsonb_typeof(x.v)='string' and length(btrim(x.v #>> '{}'))>0;
 select coalesce(jsonb_agg(btrim(x.v #>> '{}')),'[]'::jsonb) into rhythms from jsonb_array_elements(c.leadership_rhythms) x(v) where jsonb_typeof(x.v)='string' and length(btrim(x.v #>> '{}'))>0;

 -- Only goals that meet all four CORE letters. The rest are counted, not shown.
 select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',x.id,'title',x.title,'result',x.result,'outcome',x.otitle,'outcome_n',x.orn,'owner',x.owner,'end_date',x.end_date,'season',x.season,
   'risks',x.risks)) order by x.orn,x.position,x.id),'[]'::jsonb),min(x.end_date) into goals_met,first_end
 from (select g.id,g.title,g.result,g.end_date,g.season,g.position,o.title as otitle,o.rn as orn,coalesce(a.name,g.owner_name) as owner,
    (select jsonb_agg(r.text order by r.created_at,r.id) from private.goal_risks gr join private.risks r on r.id=gr.risk_id and r.engagement_id=gr.engagement_id
      where gr.goal_id=g.id and gr.engagement_id=g.engagement_id and not gr.deleted and not r.deleted) as risks
   from private.goals g
    join (select y.id,y.engagement_id,y.title,row_number() over(order by y.position,y.id) as rn from private.vision_outcomes y where y.engagement_id=p_engagement and not y.deleted) o on o.id=g.outcome_id and o.engagement_id=g.engagement_id
    left join public.attendees a on a.id=g.owner_attendee_id and a.engagement_id=g.engagement_id
   where g.engagement_id=p_engagement and not g.deleted and (private.goal_core(g.id)->>'met')::boolean) x;
 select count(*)::integer into unmet from private.goals g where g.engagement_id=p_engagement and not g.deleted and not coalesce((private.goal_core(g.id)->>'met')::boolean,false);

 -- This season is the first season any goal ends in.
 if first_end is not null then
  this_end:=private.season_end(first_end);
  season_label:=case private.season_of(first_end) when 'SEP_DEC' then 'Sept to Dec' when 'JAN_APR' then 'Jan to Apr' else 'May to Aug' end||' '||extract(year from this_end)::integer;
  select coalesce(jsonb_agg(x.v),'[]'::jsonb) into season_goals from jsonb_array_elements(goals_met) x(v) where (x.v->>'end_date')::date<=this_end;
 else season_goals:='[]'::jsonb; end if;

 select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('text',m.text,'rank',m.rank)) order by m.rank nulls last,m.created_at,m.id),'[]'::jsonb) into metrics
 from (select * from private.key_metrics k where k.engagement_id=p_engagement and not k.deleted order by k.rank nulls last,k.created_at,k.id limit 8) m;
 select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('text',m.text,'theme',nullif(m.theme,''))) order by m.created_at,m.id),'[]'::jsonb) into celebs
 from (select * from private.celebrations k where k.engagement_id=p_engagement and not k.deleted order by k.created_at,k.id limit 12) m;

 -- Key Issues: the pre-mortem risks (most likely and most damaging first) with their mitigations, then the
 -- scribe's tensions and questions. The speaker on a scribe card is never read.
 select coalesce(jsonb_agg(u.item order by u.ord,u.sub desc,u.tie),'[]'::jsonb) into issues from (
  (select 1 as ord,(coalesce(r.likelihood,0)*coalesce(r.impact,0))::numeric as sub,r.id as tie,
    jsonb_strip_nulls(jsonb_build_object('kind','risk','text',r.text,'mitigations',(select jsonb_agg(m.text order by m.created_at,m.id) from private.risk_mitigations m
      where m.risk_id=r.id and m.engagement_id=r.engagement_id and not m.deleted))) as item
   from private.risks r where r.engagement_id=p_engagement and not r.deleted and r.merged_into is null order by 2 desc,r.id limit 6)
  union all
  (select 2,-(sc.seq)::numeric,sc.id,jsonb_build_object('kind',sc.kind,'text',sc.text)
   from private.scribe_cards sc where sc.engagement_id=p_engagement and not sc.deleted and sc.kind in ('tension','question') order by sc.seq limit 12)
 ) u;

 return jsonb_build_object('church',c.name,'title',e.title,
  'years',jsonb_build_object('base',e.base_year,'future',e.base_year+10,'vision',e.base_year+3,'outlook',e.base_year+1),
  'page1',jsonb_build_object(
   'mission',jsonb_strip_nulls(jsonb_build_object('text',btrim(c.mission),'empty',btrim(c.mission)='','why',case when btrim(c.mission)='' then 'Add it in setup' end)),
   'purpose',jsonb_strip_nulls(jsonb_build_object('text',btrim(c.purpose),'empty',btrim(c.purpose)='','why',case when btrim(c.purpose)='' then 'Add it in setup, from the Kingdom Assignment' end)),
   'values',jsonb_strip_nulls(jsonb_build_object('items',vals,'empty',jsonb_array_length(vals)=0,'why',case when jsonb_array_length(vals)=0 then 'Add them in setup' end)),
   'strategy',jsonb_strip_nulls(jsonb_build_object('text',btrim(c.strategy),'empty',btrim(c.strategy)='','why',case when btrim(c.strategy)='' then 'Add it in setup' end)),
   'future',jsonb_build_object('year',e.base_year+10,'lenses',lenses),
   'vision',jsonb_strip_nulls(jsonb_build_object('year',e.base_year+3,'outcomes',outcomes,'empty',jsonb_array_length(outcomes)=0,'why',case when jsonb_array_length(outcomes)=0 then 'No Vision Outcomes yet' end))),
  'page2',jsonb_build_object(
   'priorities',jsonb_build_object('empty',true,'why','Left for the church''s Annual Planning'),
   'outlook',jsonb_strip_nulls(jsonb_build_object('year',e.base_year+1,'goals',goals_met,'empty',jsonb_array_length(goals_met)=0,'why',case when jsonb_array_length(goals_met)=0 then 'No goal meets CORE yet' end,
     'unmet',unmet,'metrics',jsonb_strip_nulls(jsonb_build_object('items',metrics,'empty',jsonb_array_length(metrics)=0,'why',case when jsonb_array_length(metrics)=0 then 'No success measures yet' end)),
     'celebrations',jsonb_strip_nulls(jsonb_build_object('items',celebs,'empty',jsonb_array_length(celebs)=0,'why',case when jsonb_array_length(celebs)=0 then 'No celebrations yet' end)))),
   'season',jsonb_strip_nulls(jsonb_build_object('label',season_label,'goals',season_goals,'empty',jsonb_array_length(season_goals)=0,'why',case when jsonb_array_length(season_goals)=0 then 'No goal meets CORE yet' end)),
   'rhythms',jsonb_strip_nulls(jsonb_build_object('items',rhythms,'empty',jsonb_array_length(rhythms)=0,'why',case when jsonb_array_length(rhythms)=0 then 'Add them in setup' end)),
   'issues',jsonb_strip_nulls(jsonb_build_object('items',issues,'empty',jsonb_array_length(issues)=0,'why',case when jsonb_array_length(issues)=0 then 'No risks, tensions or questions yet' end))));
end $$;

-- The facilitator's read. A new version is stored only when the pages changed.
create function private.map_draft_read(p_engagement uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare pages jsonb; d private.map_drafts;
begin
 if not coalesce(private.wf_facilitates(p_engagement),false) then return jsonb_build_object('status','denied'); end if;
 pages:=private.map_assemble(p_engagement);
 if pages is null then return jsonb_build_object('status','missing'); end if;
 insert into private.map_drafts(engagement_id,pages) values(p_engagement,pages)
  on conflict(engagement_id) do update set pages=excluded.pages,version=private.map_drafts.version+1,assembled_at=clock_timestamp(),deleted=false
   where private.map_drafts.pages is distinct from excluded.pages or private.map_drafts.deleted;
 select * into d from private.map_drafts where engagement_id=p_engagement;
 return jsonb_build_object('status','ok','version',d.version,'assembled_at',d.assembled_at,'pages',d.pages);
end $$;
create function public.map_draft_read(p_engagement uuid) returns jsonb
language sql security invoker set search_path='' as $$ select private.map_draft_read(p_engagement) $$;
revoke all on function private.map_assemble(uuid),private.map_draft_read(uuid),public.map_draft_read(uuid) from public,anon,authenticated;
grant execute on function private.map_draft_read(uuid),public.map_draft_read(uuid) to authenticated;

-- ---------- The Wayfinding templates (they ship with the app) ----------
-- Day 1 and Day 2 are placed by day and clock (church time) after the pre-call, so a template starts on
-- any date. Years in prompts stay {base year + n} and are filled live from the engagement; {lens name}
-- is filled from the engagement's lens names when the engagement is started from the template.
-- There is no Publish to CORE session in either template (Chris, November 4).
insert into private.templates(id,name,description,kind,shared,sessions) values('c1ea0000-0000-4000-8000-000000000002','Wayfinding',
